    G.forceEvent('meteor');
    const e = spawn('crawler', .5, { noScale: true });
    let dead = false;
    for (let i = 0; i < 60 * 16 && !dead; i++) { R(1); if (!e.alive && !e.leaked) dead = true; }
    ok('T20', dead, 'meteor killed');
    backToBuild();
  }

  // T21 fog cuts range and reverts
