  aiDiff = diffKey(diff);
  profile = AI_PROFILES[aiDiff];
  mode = 'play'; paused = false;
  playerScore = 0; aiScore = 0;
  matchTime = 0; winner = null; lastScorer = null;
  nanFlag = false; noAutoWarned = false;
  newBestFlag = false;
