    ctx.restore();
    return;
  }
  if (phase === 'goal') {
    const mine = lastScorer === 'p1';
    const color = mine ? '#9cf7ff' : '#ffc07b';
    ctx.save();
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.globalAlpha = clamp(goalT / .55, 0, 1);
    ctx.font = '800 50px "Microsoft YaHei",sans-serif';
    ctx.fillStyle = color; ctx.shadowColor = color; ctx.shadowBlur = 28;
    ctx.fillText('进 球', W / 2, MID_Y - 22);
