// "More games" always returns to the hosting site root.
(function () {
  function goHome() {
    try {
      if (window.parent && window.parent !== window) {
        window.parent.location.href = '/';
        return;
      }
    } catch (e) { }
    try { window.location.href = '/'; } catch (e2) { }
