    G.release('KeyW');
    G.step(1);
  });
  await page.waitForTimeout(60);
  await page.screenshot({ path: path.join(OUT, `game-round${round}.png`) });

  // real mouse drag smoke (outside the assertion suite, local mode = no AI goals)
  await page.evaluate(() => {
    const G = window.__G;
